def get_catalog() -> list[dict]:
    return CATALOG


def find_by_id(obj_id: str) -> dict | None:
    obj_id_lower = obj_id.lower()
    for obj in CATALOG:
        if obj["id"].lower() == obj_id_lower:
            return obj
    return None
